import org.junit.jupiter.api.*;
import org.junit.jupiter.api.MethodOrderer;
import org.junit.jupiter.api.TestMethodOrder;

import static org.junit.jupiter.api.Assertions.*;
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
public class BVA_SBAR {
    static final String TestURL = "https://www.amazon.com.tr/";
    private static Bot bot;

    @BeforeEach
    void setup() {
        bot = new Bot(TestURL,false);
        bot.connect();
    }

    @AfterEach
    void teardown() {
        bot.quit();
    }


    @Test
    @Order(1)
    @DisplayName("B1 on null search query system must returned site to main page")
    public void NullSearchTest() {
        String query = "";
        bot.makeSearch(query);
        assertEquals("Amazon.com.tr: Elektronik, bilgisayar, akıllı telefon, kitap, oyuncak, yapı market, ev, mutfak, oyun konsolları ürünleri ve daha fazlası için internet alışveriş sitesi", bot.getTabtitle());
    }

    @Test
    @Order(2)
    @DisplayName("B2 The System must work normally with a string of 1 character in length")
    public void oneCharSearchTest() {
        String query = "a";
        bot.makeSearch(query);
        assertEquals("Amazon.com.tr : "+query, bot.getTabtitle());
    }

    @Test
    @Order(3)
    @DisplayName("B3 The System must normally with a string of nominal character (e.g 6 laptop) in length")
    public void nominalSearchTest() {
        String query = "laptop";
        bot.makeSearch(query);
        assertEquals("Amazon.com.tr : "+query, bot.getTabtitle());
    }

    @Test
    @Order(4)
    @DisplayName("B4 The System must work normally with a string of length max-1")
    public void maxminusSearchTest() {
        String query = "";
        bot.makeSearch(query);
        assertEquals("Amazon.com.tr : "+query, bot.getTabtitle());
    }

    @Test
    @Order(5)
    @DisplayName("B5 The System must work normally with a string of max acceptable length")
    public void maxSearchTest() {
        String query = "";
        bot.makeSearch(query);
        assertEquals("Amazon.com.tr : "+query, bot.getTabtitle());
    }

    @Test
    @Order(6)
    @DisplayName("B6 The system should not be able to process data that is longer than the maximum allowed length")
    public void maxplusSearchTest() {
        String query = "";
        bot.makeSearch(query);
        assertNotEquals("Amazon.com.tr : "+query, bot.getTabtitle());
    }

}
